mapper.insert:
insert into sys_read_record
	(user_id, work_id, chapter_id, read_duration, read_progress, created_at, create_by, create_time, remark)
select #{userId}, #{workId}, #{chapterId}, 0, 0.00, now(), cast(#{userId} as char), now(), ''
from dual
where not exists (
	select 1 from sys_read_record r
	where r.user_id = #{userId}
	  and r.chapter_id = #{chapterId}
	  and r.created_at >= curdate()
)
